        DeviceEventCreator creator = newCreator(scopeId);

        creator.setDeviceId(deviceId);
        creator.setAction(KapuaMethod.CREATE);
        creator.setReceivedOn(new Date(receivedOn.getTime()));
        creator.setResource(resource);

        return creator;
    }

